        isolatedModules: true,
      },
    ],
  },
  testPathIgnorePatterns: ["<rootDir>/node_modules/", "<rootDir>/.next/"],
  transformIgnorePatterns: [
    "/node_modules/(?!(markdown-it|mdurl|uc.micro|punycode\\.js|entities|linkify-it)/)",
  ],
};

export default config;

