  });

  it("renders subtitle when provided", () => {
    render(
      <Section title="Title" subtitle="A description">
        <p>content</p>
      </Section>
    );
    expect(screen.getByText("A description")).toBeInTheDocument();
  });

  it("does not render subtitle element when not provided", () => {
    render(
      <Section title="Title">
        <p>content</p>
      </Section>
    );
    // The children has a <p>, but there should be no subtitle paragraph with class
    const subtitleEl = document.querySelector('[class*="subtitle"]');
    expect(subtitleEl).toBeNull();
  });

  it("applies custom className", () => {
    const { container } = render(
      <Section title="Title" className="custom-class">
        <p>content</p>
      </Section>
    );
    const section = container.firstElementChild;
    expect(section?.className).toContain("custom-class");
  });

  it("renders as a <section> element", () => {
    const { container } = render(
      <Section title="Title">
        <p>content</p>
      </Section>
    );
    expect(container.firstElementChild?.tagName).toBe("SECTION");
  });
});
